def find_beautiful_sequence(k, q):
    if len(q) % k != 0:
        return "NO"

    char_count = {}
    for char in q:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    max_count = max(char_count.values())
    if max_count > k:
        return "NO"

    result = []
    i = 0
    while i < len(q):
        j = 1
        while i + j <= len(q) and len(set(q[i:i+j])) == j:
            j += 1
        result.append(q[i:i+j-1])
        i += j - 1

    return "YES\n" + "\n".join(result)

