    unique_chars = set(q)
    if len(unique_chars) < k:
        return "NO"

    def backtrack(start, current_sequence):
        if len(current_sequence) == k:
            if ''.join(current_sequence) == q:
                return True
            return False

        for i in range(start, len(q)):
            current_sequence.append(q[start:i+1])
            if backtrack(i+1, current_sequence):
                return True
            current_sequence.pop()

        return False

    for char in unique_chars:
        if backtrack(0, [char]):
            result = [''.join(current_sequence) for start, current_sequence in enumerate([[char]] * k)]
            return "YES\n" + "\n".join(result)

    return "NO"

