def find_beautiful_sequence(k, q):
    if len(q) < k:
        return "NO"

    used_chars = set()
    result = []

    def backtrack(start):
        if start == len(q):
            return True

        for end in range(start + 1, len(q) + 1):
            current = q[start:end]
            if current[0] not in used_chars:
                used_chars.add(current[0])
                result.append(current)
                if backtrack(end):
                    return True
                result.pop()
                used_chars.remove(current[0])

        return False

    if backtrack(0):
        return "YES\n" + "\n".join(result)
    else:
        return "NO"

